	(1, 1, 'Kopi Latte', '<p>tes</p>', 2, 38, 1, 'menu/latte.jpg', 1, '2024-11-26 13:46:26', '2025-06-27 04:05:26', NULL, NULL),
	(2, 1, 'Teh Hijau', '<p>tes</p>', 2, 0, 1, 'menu/teh_hijau.jpg', 1, '2025-04-18 13:48:29', '2025-06-02 03:48:17', NULL, NULL),
	(3, 1, 'tes', 'tes', 1, 111, 1, 'menu/1745036062.png', 1, '2025-04-19 04:14:22', '2025-05-18 13:09:17', '2025-05-18 13:09:17', NULL),
	(4, 1, 'testt', NULL, 1, 45345, 1243, NULL, 1, '2025-04-19 04:15:22', '2025-05-18 13:09:21', '2025-05-18 13:09:21', NULL),
	(5, 1, 'a', NULL, 2, 435436, 345435646, NULL, 1, '2025-04-19 04:16:02', '2025-05-17 12:42:29', '2025-05-17 12:42:29', NULL),
	(6, 1, 'sdf', 'sdf', 2, 567, 2345, 'menu/1745036568.png', 1, '2025-04-19 04:22:48', '2025-05-18 13:09:23', '2025-05-18 13:09:23', NULL),
	(7, 1, 'coba gambarnya', NULL, 2, 56, 34, 'menu/7f8c58cb-135e-4e1e-b0b8-f24de976bb24.png', 1, '2025-04-19 04:32:08', '2025-05-18 13:09:26', '2025-05-18 13:09:26', NULL),
	(8, 1, 'Nasi Goreng', '<p>Nasi goreng spesial dengan ayam dan telur</p>', 1, 12, 25000, 'menu/766d6624-0d25-44f4-a864-97e87801b477.jpg', 1, '2025-05-20 04:48:23', '2026-03-07 15:43:02', NULL, '[1, 2, 3, 4]'),
	(9, 1, 'Ayam Bakar', '<p>Ayam bakar dengan bumbu tradisional</p>', 1, 24, 30000, NULL, 1, '2025-05-20 04:48:23', '2026-03-07 15:19:04', NULL, NULL),
	(10, 1, 'Es Teh Manis', '<p>Teh manis segar dengan es batu</p>', 2, 94, 8000, NULL, 1, '2025-05-20 04:48:23', '2025-07-22 03:31:11', NULL, NULL),
	(11, 1, 'Sate Ayam', '<p>Sate ayam dengan saus kacang</p>', 1, 34, 20000, NULL, 1, '2025-05-20 04:48:23', '2025-07-22 13:34:12', NULL, NULL),
	(12, 1, 'Mie Goreng', '<p>Mie goreng dengan sayuran dan daging</p>', 1, 60, 22000, NULL, 1, '2025-05-20 04:48:23', '2025-05-20 04:48:23', NULL, NULL),
	(13, 1, 'Soto Ayam', '<p>Soto ayam khas Indonesia dengan <strong>kuah kaldu</strong> yang gurih, disajikan dengan suwiran ayam, telur rebus, dan seledri.</p>', 1, 39, 22000, NULL, 1, '2025-05-20 04:50:31', '2025-06-08 12:35:29', NULL, NULL),
	(14, 1, 'Bakso Sapi', '<p>Bakso sapi lezat dengan <strong>tekstur kenyal</strong>, disajikan dengan mie kuning dan kuah bening.</p>', 1, 50, 20000, NULL, 1, '2025-05-20 04:50:31', '2025-05-20 04:50:31', NULL, NULL),
	(15, 1, 'Nasi Uduk', '<p>Nasi uduk wangi dengan <strong>santan asli</strong>, lengkap dengan ayam goreng, tempe, dan sambal kacang.</p>', 1, 34, 25000, NULL, 1, '2025-05-20 04:50:31', '2025-06-08 12:35:29', NULL, NULL),
	(16, 1, 'Gado-Gado', '<p>Salad tradisional dengan <strong>sayuran segar</strong> dan saus kacang kental, cocok untuk vegetarian.</p>', 1, 44, 18000, NULL, 1, '2025-05-20 04:50:31', '2025-06-08 12:35:29', NULL, NULL),
	(17, 1, 'Rendang Daging', '<p>Rendang daging sapi dengan <strong>bumbu rempah</strong> khas Minang, dimasak hingga empuk dan kaya rasa.</p>', 1, 24, 35000, NULL, 1, '2025-05-20 04:50:31', '2025-07-11 17:56:24', NULL, NULL),
	(18, 1, 'Es Jeruk', '<p>Minuman jeruk segar dengan <strong>perasan jeruk asli</strong>, manis dan menyegarkan.</p>', 2, 53, 10000, NULL, 1, '2025-05-20 04:50:31', '2025-07-22 13:38:04', NULL, NULL),
	(19, 1, 'Teh Tarik', '<p>Teh tarik khas Melayu dengan <strong>busa lembut</strong>, disajikan hangat atau dingin.</p>', 2, 69, 12000, NULL, 1, '2025-05-20 04:50:31', '2025-07-09 05:45:17', NULL, NULL),
	(20, 1, 'Ayam Penyet', '<p>Ayam goreng yang <strong>dipenyet</strong> dengan sambal pedas, disajikan dengan lalapan segar.</p>', 1, 30, 28000, NULL, 1, '2025-05-20 04:50:31', '2025-05-20 04:50:31', NULL, NULL),
	(21, 1, 'Nasi Kuning', '<p>Nasi kuning dengan <strong>aroma kunyit</strong>, disajikan dengan telur, ayam, dan sambal.</p>', 1, 40, 26000, NULL, 1, '2025-05-20 04:50:31', '2025-05-20 04:50:31', NULL, NULL),
	(22, 1, 'Capcay Goreng', '<p>Capcay goreng dengan <strong>sayuran segar</strong> dan potongan ayam, kaya akan rasa.</p>', 1, 35, 23000, NULL, 1, '2025-05-20 04:50:31', '2025-05-20 04:50:31', NULL, NULL),
	(23, 1, 'Es Kelapa Muda', '<p>Kelapa muda segar dengan <strong>daging kelapa</strong> asli, disajikan dingin.</p>', 2, 60, 15000, NULL, 1, '2025-05-20 04:50:31', '2025-05-20 04:50:31', NULL, NULL),
	(24, 1, 'Sop Buntut', '<p>Sop buntut sapi dengan <strong>kuah bening</strong>, disajikan dengan wortel dan kentang.</p>', 1, 20, 40000, NULL, 1, '2025-05-20 04:50:31', '2025-05-20 04:50:31', NULL, NULL),
	(25, 1, 'Martabak Telur', '<p>Martabak telur dengan <strong>isi daging cincang</strong> dan daun bawang, disajikan dengan saus.</p>', 1, 30, 25000, NULL, 1, '2025-05-20 04:50:31', '2025-05-20 04:50:31', NULL, NULL),
	(26, 1, 'Jus Alpukat', '<p>Jus alpukat creamy dengan <strong>alpukat matang</strong> dan sedikit susu.</p>', 2, 49, 15000, NULL, 1, '2025-05-20 04:50:31', '2025-07-11 17:55:20', NULL, NULL),
	(27, 1, 'Pecel Lele', '<p>Lele goreng renyah dengan <strong>sambal pecel</strong> dan lalapan segar.</p>', 1, 40, 20000, NULL, 1, '2025-05-20 04:50:31', '2025-05-20 04:50:31', NULL, NULL),
	(28, 1, 'Nasi Rawon', '<p>Nasi rawon dengan <strong>kuah hitam</strong> khas Jawa Timur, disajikan dengan daging sapi.</p>', 1, 35, 28000, NULL, 1, '2025-05-20 04:50:31', '2025-05-20 04:50:31', NULL, NULL),
	(29, 1, 'Es Campur', '<p>Es campur dengan <strong>campuran buah</strong>, agar-agar, dan sirup manis.</p>', 2, 58, 12000, NULL, 1, '2025-05-20 04:50:31', '2025-07-11 17:50:29', NULL, NULL),
	(30, 1, 'Ikan Bakar', '<p>Ikan bakar dengan <strong>bumbu kecap</strong> dan sambal, disajikan dengan lalapan.</p>', 1, 24, 30000, NULL, 1, '2025-05-20 04:50:31', '2025-06-27 04:28:09', NULL, NULL),
	(31, 1, 'Sop Iga', '<p>Sop iga sapi dengan <strong>kuah kaldu</strong> yang kaya rasa, disajikan dengan sayuran.</p>', 1, 19, 35000, NULL, 1, '2025-05-20 04:50:31', '2025-06-27 04:28:09', NULL, NULL),
	(32, 1, 'Jus Mangga', '<p>Jus mangga segar dengan <strong>mangga manis</strong>, cocok untuk cuaca panas.</p>', 2, 48, 13000, NULL, 1, '2025-05-20 04:50:31', '2025-06-02 03:48:17', NULL, NULL),
	(33, 7, 'Coba', '<p>coba menu</p>', 1, 3, 150000, NULL, 1, '2025-05-27 08:58:17', '2025-05-30 04:53:42', NULL, NULL);
